\label{prop:client_update}
Given the updated global model \(M^*\), the client update \(M_g^*\) is obtained by solving the following convex optimization problem:
\begin{equation}
\label{eq:orig_cs}
\begin{aligned}
\mathcal{J}_g(M,\mu_g): \quad \min_{M_g,\, \lambda_g,\, \{s_n\}} \quad
& \lambda_g\, r_g + \frac{1}{N_g}\sum_{n=1}^{N_g} s_n + \frac{\rho}{2}\,\|M_g - M + \mu_g\|_F^2 \\
\text{s.t.} \quad
& \max_{c \in [K]} \Bigl[ v_{(c)}^\top (M_g x_n - y_n) + 1 \Bigr] - y_n^\top M_g x_n \le s_n, \quad \forall n \in [N_g], \\
& \max_{c \in [K]} \big[ v_{(c)}^\top (M_g x_n - y) + 1 \big] - y^\top M_g x_n - \kappa\,\lambda_g \le s_n, \\
& \qquad \forall n \in [N_g],\ \forall y \in \mathcal{Y},\ y \neq y_n, \\
& \lambda_g \ge \big\| (v_{(i)} - v_{(j)})^\top M_g \big\|_*, \quad \forall i,j \in [K],
\end{aligned}
\end{equation}
where \(\|\cdot\|_*\) denotes the dual of the norm used in the transportation cost \(d(\xi,\xi')\) in \eqref{eq:cost_function}.

\label{prop:server_update}
Given the updated local models \(M_g^*\) and scaled dual variables \(\mu_g^*\), the global model is updated according to
{\setlength{\abovedisplayskip}{4pt}
\setlength{\belowdisplayskip}{4pt}
\setlength{\abovedisplayshortskip}{4pt}
\setlength{\belowdisplayshortskip}{4pt}
\begin{equation}
M^{*}
=
\sum_{g=1}^{G} \alpha_g \left(M_g^{*} + \mu_g^{*}\right).
\label{eq:global_update}
\end{equation}
}

\label{thm:composition}
Under the assumptions of Lemmas~\ref{lem:sensitivity_Mg} and~\ref{lem:sensitivity_lambda}, suppose that at each
iteration \(t=1,\ldots,T\), client \(g\) applies the Gaussian
mechanisms of Theorem~\ref{thm:dp_client_update} to the model update \(M_g^t\) and the local
DRO variable \(\lambda_g^t\), with per-variable privacy budgets
\(\epsilon_M,\epsilon_\lambda>0\) and
\(\delta_M=\delta_\lambda=\delta\).
Then the adaptive composition of the two Gaussian mechanisms over
\(T\) iterations satisfies
\((\bar{\epsilon},\bar{\delta})\)-differential privacy, where
\[
\bar{\epsilon}
=
\frac{T\left(\epsilon_M^2+\epsilon_\lambda^2\right)}{4\ln(1.25/\delta)}
+
\sqrt{
\frac{T\left(\epsilon_M^2+\epsilon_\lambda^2\right)\ln(1/\bar{\delta})}
{\ln(1.25/\delta)}
}.
\]

\label{lem:single_iter}
Assume that, for each client $g$, $h_g^{t}$ is convex and that the proximal
step sizes satisfy $\eta_g>0$ and $\nu_g>0$. Then, for any
$z_g=(M_g,\lambda_g)$ and $\mu_g$, the iterates generated by
Algorithm~\ref{alg:dp_fed_dro} satisfy
\begin{align}
&\sum_{g=1}^G \alpha_g \Big( h_g^{t}(\widetilde z_g^{\,t-1})-h_g^{t}(z_g) + \rho\big\langle \widetilde M_g^t-M_g,\ \mu_g^t\big\rangle_F + \rho\big\langle \mu_g-\mu_g^t,\ \widetilde M_g^t-M^t\big\rangle_F \Big) \notag\\
&\le \sum_{g=1}^G \alpha_g \Bigg[ \frac{\eta_g}{2} \left\| \big[h_g^{t\prime}(\widetilde z_g^{\,t-1})\big]_M - \left(\rho+\frac{1}{\eta_g}\right)\xi_g^t \right\|_F^2 + \frac{\nu_g}{2} \left| \big[h_g^{t\prime}(\widetilde z_g^{\,t-1})\big]_\lambda - \frac{1}{\nu_g}\,\zeta_g^t \right|^2 \notag\\
&\qquad - \left(\rho+\frac{1}{\eta_g}\right) \big\langle \xi_g^t,\ M_g-\widetilde M_g^{\,t-1}\big\rangle_F - \frac{1}{\nu_g}\,\zeta_g^t \big(\lambda_g-\widetilde\lambda_g^{\,t-1}\big) \notag\\
&\qquad + \frac{1}{2\eta_g} \Big( \|M_g-\widetilde M_g^{\,t-1}\|_F^2 - \|M_g-\widetilde M_g^t\|_F^2 \Big) + \frac{1}{2\nu_g} \Big( (\lambda_g-\widetilde\lambda_g^{\,t-1})^2 - (\lambda_g-\widetilde\lambda_g^t)^2 \Big) \notag\\
&\qquad + \frac{\rho}{2} \Big( \|M_g-M^{t-1}\|_F^2 - \|M_g-M^{t}\|_F^2 \Big) + \frac{\rho}{2} \Big( \|\mu_g-\mu_g^{t-1}\|_F^2 - \|\mu_g-\mu_g^{t}\|_F^2 \Big) \Bigg].
\label{eq:lemma3}
\end{align}

\label{thm:ergodic_convergence_dp_fed_dro}
Assume that, for each client \(g=1,\dots,G\) and round \(t=1,\dots,T\), the local objective \(h_g^{t}\) is convex in \(z_g\), and that, over the finite training horizon \(T\), its subgradients along the trajectory of Algorithm~\ref{alg:dp_fed_dro} are bounded as \(\|\partial_{M_g}(h_g-R_g)\|_F\le\sqrt{2}\,L\), \(|\partial_{\lambda_g}(h_g-R_g)|\le S:=\max\{r_g,\kappa-r_g\}\), \(\|\partial_{M_g}R_g\|_F\le\sqrt{2}\,C\), and \(|\partial_{\lambda_g}R_g|\le V\), for constants \(L,C,V>0\). Let \(c_M,c_{\lambda,g}>0\) satisfy \(\|M^\star\|_F\le c_M\) and \(|\lambda_g^\star|\le c_{\lambda,g}\) for all \(g\), and let the step sizes be chosen as
\begin{equation}
\eta_g := \frac{c_M}{\sqrt{T\left(2(L+C)^2+\frac{16KPL^2\ln(1.25/\delta_M)}{N_g^2\epsilon_M^2}\right)}},
\qquad
\nu_g := \frac{c_{\lambda,g}}{\sqrt{T\left((S+V)^2+\frac{2\kappa^2\ln(1.25/\delta_\lambda)}{N_g^2\epsilon_\lambda^2}\right)}}.
\label{eq:eta_nu_choice_final}
\end{equation}
Define
\begin{equation}
M_{1,T} := c_M \sum_{g=1}^G \alpha_g \Bigl( 2(L+C)^2 + \frac{16KPL^2\ln(1.25/\delta_M)}{N_g^2\epsilon_M^2} \Bigr)^{1/2} + \sum_{g=1}^G \alpha_g\, c_{\lambda,g} \Bigl( (S+V)^2 + \frac{2\kappa^2\ln(1.25/\delta_\lambda)}{N_g^2\epsilon_\lambda^2} \Bigr)^{1/2},
\label{eq:M1_final}
\end{equation}
and
\begin{equation}
M_2 := \frac{\rho}{2}c_M^2 + \frac{\beta^2}{2\rho}.
\label{eq:M2_final}
\end{equation}
Then, for any \(T\ge 1\) and any \(\beta>0\), we have
\begin{equation}
\mathbb{E}\Biggl[ \frac{1}{T}\sum_{t=1}^{T}\sum_{g=1}^G \alpha_g \Bigl( h_g^{t}(\widetilde z_g^{\,t-1})-h_g^{t}(z_g^\star) \Bigr) + \beta\sum_{g=1}^G \alpha_g \|\bar{\widetilde M}_g^{\,T}-\bar M^{\,T}\|_F \Biggr] \le \frac{M_{1,T}}{\sqrt{T}} + \frac{M_2}{T}.
\label{eq:final_theorem_fixed}
\end{equation}

Given the updated global model \(M^\star\), client \(g\) updates its local model by minimizing the augmented local Lagrangian with respect to \((M_g,\lambda_g)\). By the same problem separability argument used in Proposition~1 of \citet{ibrahim2024federated}, this update is obtained from
\begin{align}
\inf_{M_g}\; \mathcal L_{\rho,g}(M_g,M^\star,\mu_g)
&= \inf_{M_g}\; \sup_{\mathbb Q_g\in \mathcal A^{(g)}_{r_g,1,d}(\Xi)} \mathbb E^{\mathbb Q_g}\!\left[\ell_{\mathrm{CS}}(M_g;\xi)\right] + \frac{\rho}{2}\|M_g-M^\star+\mu_g\|_F^2
\label{eq:prop41_pf_1}\\
&= \inf_{M_g,\lambda_g\ge 0} \bigg\{ \lambda_g r_g + \frac{1}{N_g}\sum_{n=1}^{N_g} \sup_{\xi\in\Xi} \bigl( \ell_{\mathrm{CS}}(M_g;\xi)-\lambda_g d(\xi,\hat\xi_n) \bigr) \notag\\
&\qquad + \frac{\rho}{2}\|M_g-M^\star+\mu_g\|_F^2 \bigg\}.
\label{eq:prop41_pf_2}
\end{align}

Introducing slack variables \(\{s_n\}_{n=1}^{N_g}\), we obtain
\begin{equation}
\label{eq:prop41_pf_3}
\begin{aligned}
&\sup_{\mathbb Q_g\in\mathcal A^{(g)}_{r_g,1,d}(\Xi)} \mathbb E^{\mathbb Q_g}\!\left[\ell_{\mathrm{CS}}(M_g;\xi)\right] \\
&\qquad = \begin{aligned}[t]
\inf_{\lambda_g,\{s_n\}} \quad & \lambda_g r_g + \frac{1}{N_g}\sum_{n=1}^{N_g}s_n \\
\text{s.t.}\quad & \sup_{\xi\in\Xi} \left( \ell_{\mathrm{CS}}(M_g;\xi) - \lambda_g d(\xi,\hat\xi_n) \right) \le s_n, \quad \forall n\in[N_g], \quad \lambda_g\ge 0.
\end{aligned}
\end{aligned}
\end{equation}

Since the inner supremum in \eqref{eq:prop41_pf_3} has the same Wasserstein robust structure as in the centralized multiclass DRO formulation, Theorem~1 in \citet{ibrahim2024wasserstein} applies here with \(M\) replaced by \(M_g\). Therefore, the constraints in \eqref{eq:prop41_pf_3} are equivalently rewritten as the following:
\begin{align}
\ell_{\mathrm{CS}}(M_g;x_n,y_n) &\le s_n,
\qquad \forall n\in[N_g],
\label{eq:prop41_pf_4}
\\
\ell_{\mathrm{CS}}(M_g;x_n,y)-\kappa\lambda_g &\le s_n,
\qquad
\forall n\in[N_g],\ \forall y\in\mathcal Y,\ y\neq y_n,
\label{eq:prop41_pf_5}
\\
\lambda_g &\ge \|(v_{(i)}-v_{(j)})^\top M_g\|_*,
\quad i,j\in[K].
\label{eq:prop41_pf_6}
\end{align}

Substituting \eqref{eq:prop41_pf_4}--\eqref{eq:prop41_pf_6}
into the clientwise augmented Lagrangian subproblem yields the
optimization problem stated in Proposition~\ref{prop:client_update}.

Define the privacy losses associated with the perturbed model
update and local DRO variable at iteration \(t\) by
\begin{equation}
c_M(Z)
:=
\log\!\left(
\frac{p_M(Z)}{q_M(Z)}
\right),
\qquad
c_\lambda(z)
:=
\log\!\left(
\frac{p_\lambda(z)}{q_\lambda(z)}
\right),
\label{eq:comp_pf_1}
\end{equation}
where
\begin{equation}
\begin{aligned}
p_M(Z)
&:=
p_{\widetilde M_g^{\,t}\mid D}(Z),
&
q_M(Z)
&:=
p_{\widetilde M_g^{\,t}\mid D'}(Z),
\\
p_\lambda(z)
&:=
p_{\widetilde\lambda_g^{\,t}\mid D}(z),
&
q_\lambda(z)
&:=
p_{\widetilde\lambda_g^{\,t}\mid D'}(z),
\end{aligned}
\label{eq:comp_pf_2}
\end{equation}
are the corresponding densities under adjacent datasets
\(D\) and \(D'\).

For any real \(\tau>0\), define
\begin{equation}
\begin{aligned}
E_{M,1}
&:=
\mathbb E_{Z\sim p_M}
\left[
\left(\frac{p_M(Z)}{q_M(Z)}\right)^\tau
\right],
&
E_{M,2}
&:=
\mathbb E_{Z\sim q_M}
\left[
\left(\frac{q_M(Z)}{p_M(Z)}\right)^\tau
\right],
\\
E_{\lambda,1}
&:=
\mathbb E_{z\sim p_\lambda}
\left[
\left(\frac{p_\lambda(z)}{q_\lambda(z)}\right)^\tau
\right],
&
E_{\lambda,2}
&:=
\mathbb E_{z\sim q_\lambda}
\left[
\left(\frac{q_\lambda(z)}{p_\lambda(z)}\right)^\tau
\right].
\end{aligned}
\label{eq:comp_pf_3}
\end{equation}
The corresponding log moments are
\begin{equation}
\alpha_{M,g,t}(\tau)
:=
\log\max\{E_{M,1},E_{M,2}\},
\qquad
\alpha_{\lambda,g,t}(\tau)
:=
\log\max\{E_{\lambda,1},E_{\lambda,2}\}.
\label{eq:comp_pf_4}
\end{equation}

Consider first the perturbed model update
\begin{equation}
\widetilde M_g^{\,t}
=
M_g^{\,t}(D)+\xi_g^{\,t},
\qquad
\xi_g^{\,t}
\sim
\mathcal N\!\left(
0,\sigma_{M,g}^2 I_{KP}
\right).
\label{eq:comp_pf_release}
\end{equation}

The two neighboring output laws are Gaussian with identical covariance
\(\sigma_{M,g}^2 I_{KP}\) and means
\(\mu=\operatorname{vec}(M_g^{\,t}(D))\) and
\(\mu'=\operatorname{vec}(M_g^{\,t}(D'))\). By
Lemma 1,
\begin{equation}
\label{eq:comp_pf_sensitivity}
\begin{aligned}
\|\mu-\mu'\|_2
&=
\|M_g^{\,t}(D)-M_g^{\,t}(D')\|_F
\le
\Delta_{M,g},
\\
\Delta_{M,g}
&:=
\left(\rho+\frac{1}{\eta_g}\right)^{-1}
\frac{2\sqrt{2}L}{N_g}.
\end{aligned}
\end{equation}


By rotational invariance of the Gaussian distribution, the worst
case depends only on the mean separation
\(\Delta_{M,g}\), so the problem reduces to the
one-dimensional pair
\[
p_M(z_M)
=
\frac{1}{\sqrt{2\pi}\,\sigma_{M,g}}
\exp\!\left(
-\frac{z_M^2}{2\sigma_{M,g}^2}
\right),
\]
\[
q_M(z_M)
=
\frac{1}{\sqrt{2\pi}\,\sigma_{M,g}}
\exp\!\left(
-\frac{(z_M-\Delta_{M,g})^2}
{2\sigma_{M,g}^2}
\right).
\]
Hence,
\begin{equation}
\frac{p_M(z_M)}{q_M(z_M)}
=
\exp\!\left(
\frac{\Delta_{M,g}^2}
{2\sigma_{M,g}^2}
-
\frac{\Delta_{M,g}}
{\sigma_{M,g}^2}z_M
\right).
\label{eq:comp_pf_6}
\end{equation}

Substituting \eqref{eq:comp_pf_6} into \eqref{eq:comp_pf_3} gives
\begin{equation}
\mathbb E_{z_M\sim p_M}
\left[
\left(
\frac{p_M(z_M)}{q_M(z_M)}
\right)^\tau
\right]
=
\exp\!\left(
\tau
\frac{\Delta_{M,g}^2}
{2\sigma_{M,g}^2}
\right)
\mathbb E_{z_M\sim
\mathcal N(0,\sigma_{M,g}^2)}
\left[
\exp\!\left(
-\tau
\frac{\Delta_{M,g}}
{\sigma_{M,g}^2}
z_M
\right)
\right].
\label{eq:comp_pf_7}
\end{equation}


Using the moment generating function of a Gaussian random variable, $\mathbb E[e^{a z_M}]
=
\exp\!\left(
\frac{a^2\sigma_{M,g}^2}{2}
\right),$
with $a
=
-\tau
\frac{\Delta_{M,g}}
{\sigma_{M,g}^2},$
we obtain
\begin{equation}
E_{M,1}
=
\exp\!\left(
\frac{\tau(\tau+1)}{2}
\frac{\Delta_{M,g}^2}
{\sigma_{M,g}^2}
\right).
\label{eq:comp_pf_9a}
\end{equation}

Since the Gaussian moment-generating function is finite for every
real argument, the preceding calculation holds for every real
\(\tau>0\). By symmetry, \(E_{M,2}=E_{M,1}\).
Therefore, from the definition of
\(\alpha_{M,g,t}(\tau)\), we have
\begin{equation}
\alpha_{M,g,t}(\tau)
=
\log \max\{E_{M,1},E_{M,2}\}
\le
\frac{\tau(\tau+1)}{2}
\frac{\Delta_{M,g}^2}
{\sigma_{M,g}^2}.
\label{eq:comp_pf_9}
\end{equation}

Similarly, consider the perturbed local DRO variable
\begin{equation}
\widetilde{\lambda}_g^{\,t}
=
\lambda_g^{\,t}(D)
+
\zeta_g^{\,t},
\qquad
\zeta_g^{\,t}
\sim
\mathcal N\!\left(
0,\sigma_{\lambda,g}^2
\right).
\label{eq:comp_pf_lambda_release}
\end{equation}

The two neighboring output laws are Gaussian with identical variance
\(\sigma_{\lambda,g}^2\) and means
\(\lambda_g^{\,t}(D)\) and
\(\lambda_g^{\,t}(D')\). By
Lemma 2,
\begin{equation}
\left|
\lambda_g^{\,t}(D)
-
\lambda_g^{\,t}(D')
\right|
\le
\Delta_{\lambda,g},
\qquad
\Delta_{\lambda,g}
:=
\frac{\kappa\nu_g}{N_g}.
\label{eq:comp_pf_lambda_sensitivity}
\end{equation}

Since the mechanism is scalar-valued, the neighboring Gaussian
distributions can be reduced by translation to
\[
p_\lambda(z_\lambda)
=
\frac{1}{\sqrt{2\pi}\,\sigma_{\lambda,g}}
\exp\!\left(
-\frac{z_\lambda^2}
{2\sigma_{\lambda,g}^2}
\right),
\]
and
\[
q_\lambda(z_\lambda)
=
\frac{1}{\sqrt{2\pi}\,\sigma_{\lambda,g}}
\exp\!\left(
-\frac{(z_\lambda-\Delta_{\lambda,g})^2}
{2\sigma_{\lambda,g}^2}
\right).
\]


Hence,
\begin{equation}
\frac{p_\lambda(z_\lambda)}
{q_\lambda(z_\lambda)}
=
\exp\!\left(
\frac{\Delta_{\lambda,g}^2}
{2\sigma_{\lambda,g}^2}
-
\frac{\Delta_{\lambda,g}}
{\sigma_{\lambda,g}^2}
z_\lambda
\right).
\label{eq:comp_pf_lambda_ratio}
\end{equation}

Substituting \eqref{eq:comp_pf_lambda_ratio} into the definition of
\(E_{\lambda,1}\) gives
\begin{align}
E_{\lambda,1}
&=
\exp\!\left(
\tau
\frac{\Delta_{\lambda,g}^2}
{2\sigma_{\lambda,g}^2}
\right)
\mathbb E_{z_\lambda\sim
\mathcal N(0,\sigma_{\lambda,g}^2)}
\left[
\exp\!\left(
-\tau
\frac{\Delta_{\lambda,g}}
{\sigma_{\lambda,g}^2}
z_\lambda
\right)
\right]
\notag\\
&=
\exp\!\left(
\frac{\tau(\tau+1)}{2}
\frac{\Delta_{\lambda,g}^2}
{\sigma_{\lambda,g}^2}
\right).
\label{eq:comp_pf_lambda_moment}
\end{align}

By symmetry, \(E_{\lambda,2}=E_{\lambda,1}\). Therefore,
\begin{equation}
\alpha_{\lambda,g,t}(\tau)
=
\log\max\{E_{\lambda,1},E_{\lambda,2}\}
\le
\frac{\tau(\tau+1)}{2}
\frac{\Delta_{\lambda,g}^2}
{\sigma_{\lambda,g}^2}.
\label{eq:comp_pf_lambda}
\end{equation}

Since the Gaussian mechanisms are calibrated as
\[
\sigma_{M,g}
=
\Delta_{M,g}
\frac{\sqrt{2\ln(1.25/\delta_M)}}{\epsilon_M},
\qquad
\sigma_{\lambda,g}
=
\Delta_{\lambda,g}
\frac{\sqrt{2\ln(1.25/\delta_\lambda)}}{\epsilon_\lambda},
\]
it follows that
\begin{equation}
\alpha_{M,g,t}(\tau)
\le
\frac{\tau(\tau+1)\epsilon_M^2}
{4\ln(1.25/\delta_M)},
\label{eq:comp_pf_M}
\end{equation}
and
\begin{equation}
\alpha_{\lambda,g,t}(\tau)
\le
\frac{\tau(\tau+1)\epsilon_\lambda^2}
{4\ln(1.25/\delta_\lambda)}.
\label{eq:comp_pf_lambda_cal}
\end{equation}

We set \(\delta_M=\delta_\lambda=\delta\). By the moments accountant composition theorem of \citet{abadi2016deep}, the log moments of the two mechanisms add within each iteration and across the \(T\) iterations. Hence,
\begin{align}
\alpha_g(\tau)
&\le
\sum_{t=1}^T
\left[
\alpha_{M,g,t}(\tau)
+
\alpha_{\lambda,g,t}(\tau)
\right]
\notag\\
&\le
T\,
\frac{\tau(\tau+1)\left(\epsilon_M^2+\epsilon_\lambda^2\right)}
{4\ln(1.25/\delta)}.
\label{eq:comp_pf_13}
\end{align}


Applying the tail bound from \citet{abadi2016deep}, for any
\(\bar\epsilon>0\),
\begin{equation}
\inf_{\tau>0}
\exp\!\bigl(\alpha_g(\tau)-\tau\bar\epsilon\bigr)
\le
\inf_{\tau>0}
\exp\!\left(
T\,\frac{\tau(\tau+1)\left(\epsilon_M^2+\epsilon_\lambda^2\right)}
{4\ln(1.25/\delta)}
-
\tau\bar\epsilon
\right).
\label{eq:comp_pf_14}
\end{equation}

We now choose \(\bar\epsilon\) so that the tail bound in
\eqref{eq:comp_pf_14} is at most \(\bar\delta\). Define
\begin{equation}
A
:=
\frac{T\left(\epsilon_M^2+\epsilon_\lambda^2\right)}{4\ln(1.25/\delta)}.
\label{eq:comp_pf_15}
\end{equation}
Then \eqref{eq:comp_pf_13} can be written as
\begin{equation}
\alpha_g(\tau)
\le
A\tau(\tau+1).
\label{eq:comp_pf_16}
\end{equation}

It is sufficient that, for some \(\tau>0\),
\begin{equation}
\exp\!\left(\alpha_g(\tau)-\tau\bar\epsilon\right)
\le
\bar\delta .
\label{eq:comp_pf_17}
\end{equation}
Using the upper bound in \eqref{eq:comp_pf_16}, it is
sufficient that
\begin{align}
A\tau(\tau+1)-\tau\bar\epsilon
&\le
-\ln(1/\bar\delta),
\label{eq:comp_pf_18}\\
\tau\bar\epsilon
&\ge
A\tau(\tau+1)+\ln(1/\bar\delta),
\label{eq:comp_pf_19}\\
\bar\epsilon
&\ge
A(\tau+1)
+
\frac{\ln(1/\bar\delta)}{\tau}.
\label{eq:comp_pf_20}
\end{align}
Therefore, it is sufficient to choose
\begin{equation}
\bar\epsilon
\ge
\inf_{\tau>0}
\left\{
A(\tau+1)
+
\frac{\ln(1/\bar\delta)}{\tau}
\right\}.
\label{eq:comp_pf_21}
\end{equation}
Define
\begin{equation}
\varphi(\tau)
:=
A(\tau+1)
+
\frac{\ln(1/\bar\delta)}{\tau}.
\label{eq:comp_pf_22}
\end{equation}
The first-order condition gives
\begin{equation}
\varphi'(\tau)
=
A
-
\frac{\ln(1/\bar\delta)}{\tau^2}
=
0,
\qquad
\tau^\star
=
\sqrt{
\frac{\ln(1/\bar\delta)}{A}
}.
\label{eq:comp_pf_23}
\end{equation}
Substituting \(\tau^\star\) into \eqref{eq:comp_pf_22} yields
\begin{equation}
\inf_{\tau>0}\varphi(\tau)
=
\varphi(\tau^\star)
=
A+2\sqrt{A\ln(1/\bar\delta)}.
\label{eq:comp_pf_24}
\end{equation}
Thus, the adaptive composition over \(T\) iterations satisfies
\((\bar\epsilon,\bar\delta)\)-differential privacy for
\begin{equation}
\bar\epsilon
=
A
+
2\sqrt{A\ln(1/\bar\delta)}.
\label{eq:comp_pf_25}
\end{equation}
Substituting the definition of \(A\) from \eqref{eq:comp_pf_15}, we obtain
\begin{equation}
\bar\epsilon
=
\frac{T\left(\epsilon_M^2+\epsilon_\lambda^2\right)}{4\ln(1.25/\delta)}
+
\sqrt{
\frac{T\left(\epsilon_M^2+\epsilon_\lambda^2\right)\ln(1/\bar\delta)}
{\ln(1.25/\delta)}
}.
\label{eq:comp_pf_26}
\end{equation}
